pub enum Msg {
    Ping,
    Hello(String),
    Heartbeat(u32),
}

pub fn decode(bytes: &str) -> Result<Msg, String> {
    if let Some(hello) = bytes.strip_prefix("v:2|hello:") {
        return Ok(Msg::Hello(hello.into()));
    }
    if let Some(sequence) = bytes.strip_prefix("v:2|heartbeat:") {
        return sequence
            .parse()
            .map(Msg::Heartbeat)
            .map_err(|_| "invalid heartbeat sequence".into());
    }
    if bytes.contains("ping") {
        return Ok(Msg::Ping);
    }
    Err("unknown".into())
}

pub fn encode(msg: &Msg) -> String {
    match msg {
        Msg::Ping => "ping".into(),
        Msg::Hello(name) => format!("v:2|hello:{name}"),
        Msg::Heartbeat(sequence) => format!("v:2|heartbeat:{sequence}"),
    }
}

pub fn ping_roundtrip() -> Result<Msg, String> {
    decode(&encode(&Msg::Ping))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn decodes_ping_frame() {
        assert!(matches!(decode("ping"), Ok(Msg::Ping)));
    }

    #[test]
    fn heartbeat_roundtrip() {
        let message = Msg::Heartbeat(42);
        assert!(matches!(decode(&encode(&message)), Ok(Msg::Heartbeat(42))));
    }
}
